// Region display names pinned to CLDR 49 (generated by scripts/build-region-names.mjs).
//
// Not Intl.DisplayNames: its names come from the runtime's ICU, which differs between the
// Node that prerenders pages and each browser (English "Hong Kong SAR China" in Node 26,
// "Hong Kong" in Chromium). Text that differs between prerender and hydration is React
// error #418. A pinned table renders the same string everywhere.
//
// English is bundled; Persian and Turkish load with their UI strings (see loadLocale).
import type { Locale } from "./direction";
import en from "./regions/en.json";

type Names = Record<string, string>;

const tables: Partial<Record<Locale, Names>> = { en };

const regionLoaders: Record<Exclude<Locale, "en">, () => Promise<{ default: Names }>> = {
  fa: () => import("./regions/fa.json"),
  tr: () => import("./regions/tr.json"),
};

export async function loadRegionNames(locale: Locale): Promise<void> {
  if (locale === "en" || tables[locale]) return;
  tables[locale] = (await regionLoaders[locale]()).default;
}

/** CLDR 49 name in this locale, or null when the table has none (or is not loaded yet). */
export function regionNameOrNull(locale: Locale, iso: string): string | null {
  return tables[locale]?.[iso.toUpperCase()] ?? null;
}

/** CLDR 49 name for an ISO 3166-1 alpha-2 code; English, then the code itself, as fallbacks. */
export function regionName(locale: Locale, iso: string): string {
  return regionNameOrNull(locale, iso) ?? regionNameOrNull("en", iso) ?? iso;
}
